import { TERRAIN_LOBES } from "./gpu-terrain.ts";

// These scene coefficients are generated by Wavefield, shared with CPU tests.
const vectors = TERRAIN_LOBES.map(lobe => {
  const values = [lobe.center, lobe.depth, lobe.width, lobe.amplitude,
    lobe.lean, lobe.bend, lobe.skew, lobe.phase].map(value => value.toFixed(8));
  return `Lobe(vec4f(${values.slice(0, 4).join(",")}), vec4f(${values.slice(4).join(",")}))`;
}).join(",\n");

/** Original instanced ribbon shader. No external shader/example source. */
export const TERRAIN_SHADER = /* wgsl */ `
struct Params {
  viewport: vec4f, // CSS width, CSS height, animation seconds, effective DPR
  mesh: vec4f, // columns, rows, main count, secondary column stride
  form: vec4f, // relief, focus depth, defocus, grid contrast
  finish: vec4f, // rim light, overall opacity, vertical scale, reserved
}
struct Lobe { shape: vec4f, motion: vec4f }
const LOBES = array<Lobe, 3>(${vectors});
@group(0) @binding(0) var<uniform> params: Params;

fn height(uv: vec2f) -> f32 {
  let phase = params.viewport.z * 0.1308996939;
  var h = -0.24 - 0.05 * uv.y;
  for (var i = 0u; i < 3u; i++) {
    let lobe = LOBES[i];
    let center = lobe.shape.x + lobe.motion.x * (uv.y - 0.5)
      + lobe.motion.y * sin(3.1415926536 * uv.y + phase + lobe.motion.w);
    let q = (uv.x - center) / lobe.shape.z;
    let asymmetric = q / (1.0 + lobe.motion.z * tanh(q));
    let dz = (uv.y - lobe.shape.y) / 0.55;
    let envelope = 0.5 + 0.5 * exp(-dz * dz);
    let breathing = 0.92 + 0.08 * cos(phase + lobe.motion.w);
    h += lobe.shape.w * exp(-asymmetric * asymmetric) * envelope * breathing;
  }
  let ripple = 0.026 * sin(25.0 * uv.x + 5.0 * uv.y + phase) * cos(7.0 * uv.y - phase);
  return params.form.x * (h + ripple);
}

fn project(uv: vec2f, h: f32) -> vec2f {
  let x = params.viewport.x * (0.5 + (uv.x - 0.5) * (0.96 + 0.12 * uv.y));
  let viewY = h * 0.95 - (uv.y - 0.5) * 0.92;
  return vec2f(x, params.viewport.y * 0.54 - viewY * params.finish.z);
}

struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) local: vec2f,
  @location(1) color: vec3f,
  @location(2) alpha: f32,
  @location(3) sigma: f32,
  @location(4) segmentLength: f32,
}

@vertex fn vertexMain(@builtin(vertex_index) vertex: u32,
  @builtin(instance_index) instance: u32) -> VertexOutput {
  let columns = u32(params.mesh.x);
  let rows = u32(params.mesh.y);
  let mainCount = u32(params.mesh.z);
  let secondary = instance >= mainCount;
  var a: vec2f;
  var b: vec2f;
  if (!secondary) {
    let row = instance / columns;
    let col = instance % columns;
    a = vec2f(f32(col) / f32(columns), f32(row) / f32(rows));
    b = vec2f(f32(col + 1u) / f32(columns), a.y);
  } else {
    let index = instance - mainCount;
    let col = (index / rows) * u32(params.mesh.w);
    let row = index % rows;
    a = vec2f(f32(col) / f32(columns), f32(row) / f32(rows));
    b = vec2f(a.x, f32(row + 1u) / f32(rows));
  }
  let corners = array<vec2f, 6>(vec2f(0,-1), vec2f(1,-1), vec2f(0,1),
    vec2f(0,1), vec2f(1,-1), vec2f(1,1));
  let corner = corners[vertex];
  let uv = mix(a, b, corner.x);
  let ha = height(a);
  let hb = height(b);
  let pa = project(a, ha);
  let pb = project(b, hb);
  let segmentLength = max(length(pb - pa), 0.01);
  let tangent = (pb - pa) / segmentLength;
  let perpendicular = vec2f(-tangent.y, tangent.x);
  let focusDistance = abs(uv.y - params.form.y);
  let sigma = 0.45 + params.form.z * pow(focusDistance, 1.7) * 4.2;
  let extent = sigma * 3.4 + 0.4;
  let endpointFeather = 0.8;
  let position = mix(pa, pb, corner.x) + perpendicular * corner.y * extent
    + tangent * (corner.x * 2.0 - 1.0) * endpointFeather;

  let epsilon = 0.002;
  let du = (height(uv + vec2f(epsilon,0)) - height(uv - vec2f(epsilon,0))) / (2.0 * epsilon);
  let dv = (height(uv + vec2f(0,epsilon)) - height(uv - vec2f(0,epsilon))) / (2.0 * epsilon);
  let normal = normalize(vec3f(-du / 18.0, 1.0, -dv / 4.0));
  let diffuse = max(0.0, dot(normal, normalize(vec3f(-0.25,0.82,0.51))));
  let grazing = pow(1.0 - abs(dot(normal, normalize(vec3f(0,0.28,0.96)))), 2.3);
  let altitude = mix(ha, hb, corner.x);
  let rim = grazing * smoothstep(-0.03,0.4,altitude) * params.finish.x;
  let filmEdge = smoothstep(0.0,0.08,uv.y) * (1.0 - smoothstep(0.92,1.0,uv.y));
  let horizontalEdge = smoothstep(0.0,0.07,uv.x) * (1.0 - smoothstep(0.93,1.0,uv.x));
  let screenEdge = smoothstep(0.0,0.035,position.x / params.viewport.x)
    * (1.0 - smoothstep(0.965,1.0,position.x / params.viewport.x));
  let depthGain = 0.28 + 0.72 * smoothstep(0.05,0.55,uv.y);
  let neighbor = uv + vec2f(0, 1.0 / f32(rows));
  let spacing = abs(dot(project(neighbor, height(neighbor)) - project(uv, altitude), perpendicular));
  let coverage = select(smoothstep(0.0, 1.2, spacing), 1.0, secondary);
  let familyGain = select(1.0, 0.19, secondary);
  let lighting = 0.25 + (0.24 * diffuse + 0.65 * rim) * params.form.w;
  let alpha = lighting * familyGain * depthGain
    * filmEdge * horizontalEdge * screenEdge * coverage * params.finish.y;

  var out: VertexOutput;
  out.position = vec4f(position / params.viewport.xy * vec2f(2,-2) + vec2f(-1,1), 0, 1);
  out.local = vec2f(mix(-endpointFeather, segmentLength + endpointFeather, corner.x), corner.y * extent);
  out.color = mix(vec3f(0.18,0.44,0.7), vec3f(0.62,0.77,0.88), clamp(rim * 2.0,0.0,0.7));
  out.alpha = alpha;
  out.sigma = sigma;
  out.segmentLength = segmentLength;
  return out;
}

@fragment fn fragmentMain(in: VertexOutput) -> @location(0) vec4f {
  let crossSection = exp(-0.5 * (in.local.y / in.sigma) * (in.local.y / in.sigma));
  // Adjacent segment windows sum smoothly at a joint, without bright beads.
  let along = smoothstep(-0.8,0.8,in.local.x) * smoothstep(-0.8,0.8,in.segmentLength - in.local.x);
  let alpha = clamp(in.alpha * crossSection * along * (0.45 / in.sigma), 0.0, 0.85);
  return vec4f(in.color * alpha, alpha);
}
`;
